package com.rulecraft.decisionops.workflow.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="decision_promotion")
public class DecisionPromotion {@Id @Column(name="decision_service_id")private UUID serviceId;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="change_request_id",nullable=false)private UUID requestId;@Column(name="decision_version_id",nullable=false)private UUID decisionVersionId;@Column(name="promoted_by",nullable=false)private UUID promotedBy;@Column(name="promoted_by_name",nullable=false,length=160)private String promotedByName;@Column(name="promoted_at",nullable=false)private Instant promotedAt;@Version private long revision;protected DecisionPromotion(){}public DecisionPromotion(UUID serviceId,UUID tenantId,UUID projectId){this.serviceId=serviceId;this.tenantId=tenantId;this.projectId=projectId;}public void promote(UUID requestId,UUID versionId,UUID actor,String actorName,Instant now){this.requestId=requestId;decisionVersionId=versionId;promotedBy=actor;promotedByName=actorName;promotedAt=now;}public UUID getServiceId(){return serviceId;}public UUID getRequestId(){return requestId;}public UUID getDecisionVersionId(){return decisionVersionId;}public String getPromotedByName(){return promotedByName;}public Instant getPromotedAt(){return promotedAt;}public long getRevision(){return revision;}}
